def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return (seen[target - x], i)
        seen[x] = i
    return None

print(two_sum([2, 7, 11, 15], 9))
print(two_sum([1, 2, 3], 100))
print(two_sum([], 5))

evidence = {
    "recall@5": (0.62, 0.86),
    "p95_ms": (1400, 400),
    "cost_per_task_usd": (0.041, 0.019),
}

def delta(before, after):
    if before == 0:
        return None
    return round((after - before) / before * 100, 1)

for metric, (before, after) in evidence.items():
    print(f"{metric:<20} {before} -> {after}  ({delta(before, after)}%)")
print("measured on:", "180 eval cases", "| source:", "nightly eval log")

questions = [
    {"q": "Kitna scale karega?", "have_number": True, "have_plan": True},
    {"q": "Cost per user?", "have_number": False, "have_plan": True},
    {"q": "Security posture?", "have_number": True, "have_plan": False},
]

def gaps(qs):
    out = []
    for item in qs:
        missing = []
        if not item["have_number"]:
            missing.append("number")
        if not item["have_plan"]:
            missing.append("plan")
        if missing:
            out.append((item["q"], missing))
    return out

print(gaps(questions))
print("ready:", len(gaps(questions)) == 0)

for q, missing in gaps(questions):
    print(f"TODO: {q} -> prepare {', '.join(missing)}")
